package com.gamehubstore.promotion_mscv.services;
import com.gamehubstore.promotion_mscv.models.Promotion; import com.gamehubstore.promotion_mscv.repositories.*; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.LocalDate; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class PromotionServiceTest {
 @Test void validationCalculatesWithoutConsumingOrReserving(){PromotionRepository repo=mock(PromotionRepository.class);PromotionReservationRepository reservations=mock(PromotionReservationRepository.class);PromotionService service=new PromotionService(repo,reservations);Promotion p=promotion("SAVE10",LocalDate.now().minusDays(1),LocalDate.now().plusDays(1));when(repo.findByCodeIgnoreCase("SAVE10")).thenReturn(Optional.of(p));when(reservations.countByCodeIgnoreCaseAndStatus("SAVE10","RESERVADA")).thenReturn(0L);assertEquals(new BigDecimal("10.00"),service.validateAndCalculate("SAVE10",new BigDecimal("100")));assertEquals(0,p.getUsedCount());verify(reservations,never()).save(any());verify(repo,never()).save(any());}
 @Test void rejectsExpiredPromotion(){PromotionRepository repo=mock(PromotionRepository.class);PromotionReservationRepository reservations=mock(PromotionReservationRepository.class);PromotionService service=new PromotionService(repo,reservations);Promotion p=promotion("OLD",LocalDate.now().minusDays(8),LocalDate.now().minusDays(1));when(repo.findByCodeIgnoreCase("OLD")).thenReturn(Optional.of(p));assertThrows(IllegalArgumentException.class,()->service.validateAndCalculate("OLD",BigDecimal.TEN));}
 private Promotion promotion(String code,LocalDate start,LocalDate end){Promotion p=new Promotion();p.setCode(code);p.setType("PORCENTAJE");p.setValue(new BigDecimal("10"));p.setStartDate(start);p.setEndDate(end);p.setMinimumAmount(BigDecimal.ZERO);p.setUsedCount(0);p.setActive(true);return p;}
}
